function validate([s, k, minLength]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 1000) return 's needs 1 to 1000 characters.';
  if (!/^[1-9]+$/.test(s)) return 's may contain only the digits 1 to 9.';
  if (!Number.isInteger(k) || k < 1 || k > s.length) return 'k is between 1 and s.length.';
  if (!Number.isInteger(minLength) || minLength < 1 || minLength > s.length) return 'minLength is between 1 and s.length.';
  return null;
}

