function beautifulPartitions(s, k, minLength) {
  const MOD = 1_000_000_007;
  const n = s.length;
  const isPrime = (digit) => "2357".includes(digit);
  if (!isPrime(s[0]) || isPrime(s[n - 1])) {
    return 0;
  }

  // boundary[i]: one piece may end just before index i and the next start at i.
  const boundary = new Array(n + 1).fill(false);
  boundary[0] = true;
  boundary[n] = true;
  for (let i = 1; i < n; i++) {
    boundary[i] = !isPrime(s[i - 1]) && isPrime(s[i]);
  }

  // prev[i]: ways to cut s[0..i) into (part - 1) beautiful pieces.
  let prev = new Array(n + 1).fill(0);
  prev[0] = 1;
  for (let part = 1; part <= k; part++) {
    const curr = new Array(n + 1).fill(0);
    let ready = 0;
    for (let end = minLength; end <= n; end++) {
      const start = end - minLength;
      if (boundary[start]) {
        ready = (ready + prev[start]) % MOD;
      }
      if (boundary[end]) {
        curr[end] = ready;
      }
    }
    prev = curr;
  }
  return prev[n];
}

