function beautifulPartitions(s, k, minLength) {
  // Try every set of cut positions between characters.
  const n = s.length;
  const prime = new Set(['2', '3', '5', '7']);
  let ways = 0;
  for (let mask = 0; mask < (1 << (n - 1)); mask++) {
    const pieces = [];
    let from = 0;
    for (let i = 1; i < n; i++) {
      if (mask & (1 << (i - 1))) { pieces.push(s.slice(from, i)); from = i; }
    }
    pieces.push(s.slice(from));
    if (pieces.length !== k) continue;
    const good = pieces.every(p => p.length >= minLength && prime.has(p[0]) && !prime.has(p[p.length - 1]));
    if (good) ways++;
  }
  return ways % 1_000_000_007;
}

