function generate(rand, size) {
  const primes = '2357', others = '14689';
  const digit = isPrime => (isPrime ? primes : others)[Math.floor(rand() * (isPrime ? 4 : 5))];
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 12);
  const chars = [];
  for (let i = 0; i < n; i++) chars.push(digit(rand() < 0.5));
  // Usually make the ends fit a beautiful cutting so the answer is often non-zero.
  if (rand() < 0.8) { chars[0] = digit(true); chars[n - 1] = digit(false); }
  const s = chars.join('');
  const minLength = size === 'large' ? 1 + Math.floor(rand() * 4) : 1 + Math.floor(rand() * Math.min(n, 3));
  const most = Math.max(1, Math.floor(n / minLength));
  const k = size === 'large' ? 1 + Math.floor(rand() * Math.min(most, 150)) : 1 + Math.floor(rand() * Math.min(most, 4));
  return [s, k, minLength];
}
